from fractions import Fraction

# Spin-1 local labels; only the additive S^z charge is needed.
levels=(1,0,-1)
basis=[(a,b) for a in levels for b in levels]
idx={x:i for i,x in enumerate(basis)}

# Verify every matrix element generated by the XXZ + single-ion H_0 preserves total S^z.
# Diagonal terms are automatic. Exchange terms are S1^+S2^- and S1^-S2^+.
transitions=[]
for a,b in basis:
    if a < 1 and b > -1:
        transitions.append(((a,b),(a+1,b-1)))
    if a > -1 and b < 1:
        transitions.append(((a,b),(a-1,b+1)))
for x,y in transitions:
    assert sum(x)==sum(y)

# Build an exact block-supported symmetric matrix X representing any function of H_0.
X=[[Fraction(0) for _ in basis] for __ in basis]
for i,x in enumerate(basis):
    for j,y in enumerate(basis):
        if sum(x)==sum(y):
            X[i][j]=Fraction((i+1)*(j+1)+3, 97)
# symmetrize exactly
for i in range(9):
    for j in range(i):
        v=(X[i][j]+X[j][i])/2
        X[i][j]=X[j][i]=v

# Positive invertible local filter K=diag(k_m), chosen rationally for exact arithmetic.
k={1:Fraction(2),0:Fraction(3),-1:Fraction(5)}

def filt(A):
    Y=[[Fraction(0) for _ in basis] for __ in basis]
    for i,(a,b) in enumerate(basis):
        for j,(c,d) in enumerate(basis):
            Y[i][j]=k[a]*k[b]*A[i][j]*k[c]*k[d]
    return Y

def pt(A):
    Y=[[Fraction(0) for _ in basis] for __ in basis]
    for i,(a,b) in enumerate(basis):
        for j,(c,d) in enumerate(basis):
            Y[i][j]=A[idx[(a,d)]][idx[(c,b)]]
    return Y

lhs=pt(filt(X))
rhs=filt(pt(X))
assert lhs==rhs

# Verify the block support is exactly what makes a uniform-field Boltzmann factor split symmetrically.
# For any supported X_ij, total charges agree, so exp(beta h M_i) is split as half on each side.
for i,x in enumerate(basis):
    for j,y in enumerate(basis):
        if X[i][j]:
            assert sum(x)==sum(y)

print(f"VERIFY_OK transitions={len(transitions)} supported_entries={sum(bool(v) for row in X for v in row)} pt_entries=81")
